# AWS S3 跨区域复制 + 区域 KMS
resource "aws_kms_key" "eu_key" {
  provider = aws.eu
  description = "EU region KMS - GDPR compliant"
  policy = data.aws_iam_policy_document.eu_kms.json
}
resource "aws_s3_bucket_replication_configuration" "cross_region" {
  bucket = aws_s3_bucket.eu_data.id
  role   = aws_iam_role.replication.arn
  rule {
    id     = "gdpr-replication"
    status = "Enabled"
    destination {
      bucket        = aws_s3_bucket.eu_data_replica.arn
      encryption_configuration { replica_kms_key_id = aws_kms_key.eu_key.arn }
    }
  }
}

