  --event-pattern '{"source":["aws.s3"],"detail-type":["AWS API Call via CloudTrail"],"detail":{"eventName":["DeleteObjects"],"requestParameters":{"delete":{"objects":[{"key":[{"prefix":"backup/"}]}]}}}}'

