kp-eddos-bot.codeExample:
# Cloudflare Rate Limiting 规则
resource "cloudflare_rate_limit" "api_limit" {
  zone_id = var.cloudflare_zone_id
  threshold = 100
  period    = 60
  action {
    mode = "challenge"
    timeout = 3600
  }
  match {
    request {
      url_pattern = "/api/*"
      methods     = ["POST", "PUT"]
    }
    response {
      statuses  = [200, 429]
      origin_traffic = false
    }
  }
}

