# 多服务加密覆盖检查
for svc in ebs s3 rds; do
  case $svc in
    ebs) aws ec2 describe-volumes --query 'Volumes[?Encrypted==`false`].VolumeId' --output text ;;
    s3)  aws s3api list-buckets --query 'Buckets[].Name' --output text | tr '\t' '\n' | while read b; do aws s3api get-bucket-encryption --bucket $b 2>/dev/null || echo "UNENCRYPTED: $b"; done ;;
    rds) aws rds describe-db-instances --query 'DBInstances[?StorageEncrypted==`false`].DBInstanceIdentifier' --output text ;;
  esac
done

